  "malformed_response",  /* did not decode at all */
  "truncated",           /* stopped at the output limit */
  "timeout",
  "offline",
  "rate_limit",
  "invalid_model",       /* unknown, renamed or retired destination */
  "provider_error",
  "stale_profile"        /* O'Mono's own profile is out of date or unverified */
