    view: FIRM_VIEW_NAME,
    generated_at: new Date(Number.isFinite(o.now) ? o.now : Date.now()).toISOString(),
    organization: str(o.organization) || str(good[0] && good[0].organization) || null,
    floor: FIRM_FLOOR,
    people: people.size,
    files_read: files.length,
    files_rejected: bad.length,
