  const modeBox = doc.getElementById("permitted_modes");
  if (modeBox) {
    const boxes = modeBox.querySelectorAll("input[type=checkbox]");
    for (let i = 0; i < boxes.length; i++) if (boxes[i].checked) modes.push(boxes[i].value);
  }
  let grouping = null;
  const groupBox = doc.getElementById("grouping_dimension");
  if (groupBox) {
    const radios = groupBox.querySelectorAll("input[type=radio]");
    for (let i = 0; i < radios.length; i++) if (radios[i].checked) grouping = radios[i].value;
  }

