  L.push("  Reminder cadence: " + (s.reporting.cadence_days || "none") + " days");
  L.push("  Retention: " + (s.reporting.retention_days || "not set") + " days");
  L.push("  Curriculum package: " + yesNo(s.reporting.curriculum_output));
  L.push("  Transmission: " + s.reporting.transmission);
