  L.push("PRIVACY");
  L.push("  Individual scores: " + yesNo(s.privacy.individual_scores));
  L.push("  Drill-down to one person: " + yesNo(s.privacy.drill_down));
  L.push("  Free text in reports: " + yesNo(s.privacy.free_text));
  L.push("  Identifiers in reports: " + s.privacy.identifiers_in_reports);
  L.push("  Suppression: " + list(s.privacy.suppression));
  L.push("");
  L.push("MODULES");
  L.push("  Optional: " + list(s.optional_modules));
  L.push("");
  L.push("HOW THIS TRAVELS");
