const ENTERPRISE_REPORT_SCHEMA = "omono.enterprise-report.v3";
const COHORT_SCHEMA = "omono.firm-cohort.v3";
const CONFIG_SCHEMA = "omono.enterprise-config.v3";
const MANAGED_PROFILE_SCHEMA = "omono.managed-profile.v3";
const CURRICULUM_EVIDENCE_SCHEMA = "omono.enterprise-curriculum-evidence.v1";
const COMPLETE_TEACHING_RECORDS = "complete_records";
const INCOMPLETE_CURRENT_RECORDS = "incomplete_current_records";
const OLDER_INCOMPLETE_RECORDS = "older_incomplete_records";

