  "curriculum_evidence.relationships.#.lesson_type_ids.#",
  "curriculum_evidence.relationships.#.teaching_record_status",
  "curriculum_evidence.relationships.#.safeguards.#.id",
  "curriculum_evidence.relationships.#.safeguards.#.state",
  "curriculum_evidence.relationships.#.outcome",
  "curriculum_evidence.relationships.#.failure_category",
  "curriculum_evidence.relationships.#.repair_id",
