    action: "operational_fix",
    certainty: "supported",
    statement: "The safeguard was retained and the work still failed. This points at the model, the tool, the source route, or the workflow, and not at the person using it.",
    uncertainty: "Which of those four it is cannot be told from counts alone; the failure categories narrow it.",
    when: (o) => num(o.safeguard_retained_then_failed) >= EVIDENCE_FLOOR,
    basis: (o) => ({ safeguard_retained_then_failed: num(o.safeguard_retained_then_failed) })
