    observations: 0,
    lessons_shown: 0,
    safeguards_retained: 0,
    safeguards_removed: 0,
    verification_caught: 0,
    worked: 0,
    partly: 0,
    failed: 0,
    not_evaluated: 0,
    unknown: 0,
    failures: 0
