    schema: MAP_SCHEMA,
    scope: "personal",
    visibility: "local_only",
    generated_at: Number.isFinite(o.now) ? o.now : null,
    /* Round two (R11): the scale run showed the Learning header reading a
       `records` field this map never carried, so it said "0 prompts" over
       any record. The count is the folded events the map was built from. */
    records: list.length,
